def classificar(m):
    # Ver (cifra verbosa): uma letra vira vários glifos -> muitos glifos distintos,
    # cobertura top10 baixa, entropia h0 alta face ao alfabeto, IC próximo do uniforme.
    if m['alfabeto.glifos_distintos'] > 40 and m['alfabeto.cobertura_top10'] < 0.5:
        return 'VER'
