    if m['coincidencia.ic'] < m['coincidencia.uniforme_ic'] * 1.15 and m['alfabeto.glifos_distintos'] > 30:
        return 'VER'
    # Aleatório: IC ~ uniforme, entropia h0 ~ log2(glifos), sem estrutura
    if abs(m['coincidencia.ic'] - m['coincidencia.uniforme_ic']) < 0.005 and m['entropia.h0'] > 4.0:
        return 'ALE'
