    if m['alfabeto.glifos_distintos'] > 30 and m['coincidencia.ic'] > 0.06:
        return 'NUL'
    # Transposição: IC próximo do natural, mas h2_palavra ~ h2_fluxo (sem dependência de bigramas),
    # e IC por período constante (não há periodicidade de Vigenère).
    if m['coincidencia.ic'] > 0.06 and abs(m['entropia.h2_palavra'] - m['entropia.h2_fluxo']) < 0.05:
        # distinguir de LN: razão tipo/token muito alta e hapax quase total -> não é língua natural
        if m['palavras.razao_tipo_token'] > 0.85 and m['palavras.hapax'] > m['palavras.tipos'] * 0.9:
            return 'TRA'
    # Polialfabética: IC por período sobe em algum período face ao IC global
    if m['coincidencia.ic_por_periodo.1'] < m['coincidencia.ic'] * 1.05 and m['coincidencia.ic'] < 0.06:
        return 'POL'
    # Substituição simples: IC próximo do natural, h2_palavra > h2_fluxo, distribuição zipf razoável
    if m['coincidencia.ic'] > 0.06 and m['entropia.h2_palavra'] > m['entropia.h2_fluxo']:
        if m['zipf.r2'] > 0.6:
            return 'SUB'
    # Língua natural: IC natural, zipf bom, palavras repetidas, dependência de fronteira
    if m['coincidencia.ic'] > 0.06 and m['zipf.r2'] > 0.6 and m['dependencia.mi_fronteira'] > m['dependencia.mi_baralhado_media']:
        return 'LN'
    # Baralhado: palavras reais mas ordem aleatória -> dependência de fronteira ~ baralhado
    if abs(m['dependencia.mi_fronteira'] - m['dependencia.mi_baralhado_media']) < 0.02 and m['zipf.r2'] > 0.5:
        return 'BAR'
    # Tabela: sem estrutura linguística, IC baixo, sem zipf
    if m['zipf.r2'] < 0.5 and m['coincidencia.ic'] < 0.06:
        return 'TAB'
    return 'indeterminada'

