            if abs(m['coincidencia.ic_por_periodo.1'] - m['coincidencia.ic_por_periodo.2']) < 0.005 and abs(m['coincidencia.ic_por_periodo.2'] - m['coincidencia.ic_por_periodo.3']) < 0.005:
                # verificar se ha estrutura de palavras reais (BAR) ou nao
                if m['palavras.razao_tipo_token'] > 0.9 and m['zipf.r2'] < 0.7:
                    return 'ALE'
                if m['palavras.razao_tipo_token'] > 0.85 and m['zipf.declive'] > -0.5:
                    return 'BAR'
                # verbosa: muitos glifos por letra, h0 baixo relativo a glifos
                if m['entropia.h0'] < 4.5 and m['alfabeto.glifos_distintos'] < 25:
                    return 'VER'
                return 'SUB'
            else:
                return 'POL'
        else:
            return 'ALE'
    # Transposicao: IC alto mas h2_palavra baixo (estrutura de palavras preservada)
    if m['coincidencia.ic'] > m['coincidencia.uniforme_ic'] * 1.2:
        if m['entropia.h2_palavra'] < m['entropia.h1'] and m['palavras.comprimento_medio'] > 4:
            if m['dependencia.mi_fronteira'] > m['dependencia.mi_baralhado_media']:
                return 'TRA'
        # NUL: nulos inseridos -> IC alto mas palavras curtas/irregulares
        if m['palavras.comprimento_medio'] < 5 and m['repeticoes.palavras_repetidas_seguidas'] == 0:
            return 'NUL'
        # TAB: gerado por tabela, sem significado -> zipf fraco
        if m['zipf.r2'] < 0.7 and m['palavras.razao_tipo_token'] > 0.8:
            return 'TAB'
        return 'SUB'
    # IC baixo -> polialfabetica ou aleatorio
    if m['coincidencia.ic'] < m['coincidencia.uniforme_ic'] * 1.1:
        if m['entropia.h0'] > 4.5:
            return 'ALE'
        return 'POL'
    return 'indeterminada'

def classificar(m):
    if m['alfabeto.glifos_distintos'] <= 12 and m['coincidencia.ic'] >= m['coincidencia.uniforme_ic'] * 0.95 and m['entropia.h0'] <= 3.5:
        if m['palavras.razao_tipo_token'] > 0.8 and m['zipf.r2'] < 0.7:
            return 'ALE'
        return 'TAB'
    if m['coincidencia.ic'] > 0.06 and m['coincidencia.ic'] < 0.09:
        return 'LN'
    if m['coincidencia.ic'] > 0.05 and m['coincidencia.ic'] < 0.07:
        return 'SUB'
    if m['coincidencia.ic'] > 0.04 and m['coincidencia.ic'] < 0.06:
        return 'POL'
    if m['coincidencia.ic'] < 0.05:
        return 'TRA'
    return 'indeterminada'
